import { esc, icon, wordmark, badge, fmtDate, pct, hospitalMark, featureChips, empty, fixtureNote, paginationLabel, field, statusOf, isDemo, modeCopy, number } from './components.js';
import { FEATURES, OPERATIONS, RESOURCE, PURPOSE, REVIEWERS } from './domain.js';
export const navigation=[['overview','grid','Overview'],['warrants','document','Warrants'],['training','network','Federated training'],['security','shield','Security events'],['audit','history','Audit history']];
const latestRound=s=>s.rounds.at(-1)??{number:0,at:s.clock,modelVersion:'—',modelHash:'—',metrics:{accuracy:null,loss:null,precision:null,recall:null,f1:null,rocAuc:null},aggregation:'Not supplied',evaluation:'Not yet evaluated'};
const headers={overview:['RESEARCH GOVERNANCE','Overview','A shared model. Clearly defined permissions.'],warrants:['AUTHORIZATION','Digital warrants','Every contribution begins with an approved scope.'],training:['MODEL OPERATIONS','Federated training','Follow participation, contributions and model progression.'],security:['POLICY MONITORING','Security events','Understand what was denied, and why.'],audit:['ACCOUNTABILITY','Audit history','A traceable record of every governance decision.']};
export function landing(){return `<div class="landing"><header class="public-header">${wordmark()}<nav aria-label="Introduction navigation"><a href="#principles">The approach</a><a href="${modeCopy('#/overview','/auth/login')}" class="btn primary small">${modeCopy('View demo','Sign in')} ${icon('arrow',16)}</a></nav></header><main id="main-content"><section class="landing-hero"><div class="hero-copy"><div class="eyebrow"><span class="tiny-square"></span> FEDERATED RESEARCH, GOVERNED.</div><h1>Collaboration needs<br>a clear <em>mandate.</em></h1><p>Three hospitals. One research model. Veylance puts scoped, expiring and revocable digital warrants at the centre of federated learning.</p><div class="hero-actions"><a class="btn primary" href="#/overview">Explore the workspace ${icon('arrow')}</a><a class="demo-tag" href="/demo/#/overview"><span class="status-dot"></span> Interactive demo · synthetic data</a></div><div class="hero-footnote">A hackathon prototype for hospital readmission research.</div></div><div class="mandate-visual"><div class="visual-heading"><span>RESEARCH NETWORK</span><span>01 — 03</span></div><div class="network-line line-one"></div><div class="network-line line-two"></div><div class="network-line line-three"></div><div class="network-hospital nh-a">${hospitalMark('A')}<div><strong>Hospital A</strong><span>Scoped participation</span></div>${icon('check',16)}</div><div class="network-hospital nh-b">${hospitalMark('B')}<div><strong>Hospital B</strong><span>Scoped participation</span></div>${icon('check',16)}</div><div class="network-hospital nh-c">${hospitalMark('C')}<div><strong>Hospital C</strong><span>Scoped participation</span></div>${icon('check',16)}</div><div class="network-core">${icon('shield',31)}<strong>Veylance</strong><span>WARRANT GATE</span></div><div class="visual-caption"><span class="brass-rule"></span> Permissions travel. Hospital training records stay in their client training paths.</div></div></section><section id="principles" class="principles"><div><span class="eyebrow">THE GOVERNANCE LAYER</span><h2>Trust is a set of<br>explicit decisions.</h2></div><ol><li><span>01</span><div><h3>Agree on the scope</h3><p>A manager, risk reviewer and resource owner independently review each warrant. Narrowed permissions require requester consent.</p></div></li><li><span>02</span><div><h3>Check every contribution</h3><p>Resource, purpose, features, expiry and quota define the intended authorization boundary for each hospital.</p></div></li><li><span>03</span><div><h3>Keep the decision trail</h3><p>Revoke future participation and inspect the record. Previously aggregated updates and downloaded models remain.</p></div></li></ol></section><section class="public-disclosure">${icon('info')}<p><strong>Governance you can inspect.</strong> The live workspace runs warrant checks, a SHA-256 audit chain and Flower training on reproducible synthetic data. The interactive demo uses isolated browser-local illustrative fixtures. No clinical validation or advanced privacy guarantees are claimed.</p><a href="/demo/#/overview">Enter demo ${icon('arrow',16)}</a></section></main><footer class="public-footer">${wordmark()}<span>Purpose-bound collaboration.</span><span>Synthetic research prototype</span></footer></div>`;}
export function shell(s,ui,content,mode){const h=headers[ui.page]??headers.overview;const securityCount=s.events.length;return `<div class="workspace"><aside class="sidebar" id="sidebar">${wordmark()}<div class="sidebar-label">RESEARCH WORKSPACE</div><nav aria-label="Workspace">${navigation.map(([key,i,label])=>`<a href="#/${key}" class="nav-link ${ui.page===key?'active':''}" ${ui.page===key?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${key==='security'&&securityCount?`<span class="nav-count">${securityCount}</span>`:''}</a>`).join('')}</nav><div class="sidebar-session"><span class="sidebar-label">ACTIVE RESEARCH</span><strong>Hospital readmission</strong><span>Three-institution consortium</span><div><span class="status-dot"></span> ${mode==='demo'?'Simulation workspace':'Live workspace'}</div></div><div class="sidebar-bottom"><div class="sidebar-seal">${icon('shield',22)}<span>Scoped by design.<br><strong>Accountable by default.</strong></span></div><a href="#/">${icon('external',15)} About Veylance</a><div class="sidebar-footer">VEY / RESEARCH GOVERNANCE</div></div></aside><div class="workspace-body"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Toggle navigation" aria-expanded="false" aria-controls="sidebar">${icon('menu')}</button><div class="breadcrumb">Workspace <span>/</span> <strong>${navigation.find(n=>n[0]===ui.page)?.[2]||'Overview'}</strong></div><div class="topbar-right"><span class="demo-tag"><span class="status-dot"></span>${mode==='demo'?'Interactive demo · synthetic data':'Backend connected · synthetic data'}</span>${mode==='demo'?`<label class="role-select"><span class="avatar">EW</span><span class="sr-only">Demo actor</span><select id="demo-actor" aria-label="Demo actor">${[...REVIEWERS.map(r=>({id:r.id,label:r.label})),...s.hospitals.map(h=>({id:`requester-${h.id}`,label:`Requester · Hospital ${h.id}`}))].map(a=>`<option value="${a.id}" ${ui.actorId===a.id?'selected':''}>${a.label}</option>`).join('')}</select></label>`:`<span class="verified-user">${esc(s.user?.name)} · ${esc(s.user?.roles.join(', ')||'No role assigned')}</span><button class="text-button" data-action="logout">Sign out</button>`}</div></header><main class="main-workspace" id="main-content" tabindex="-1"><div class="page-heading"><div><div class="eyebrow">${h[0]}</div><h1>${h[1]}</h1><p>${h[2]}</p></div><div class="page-actions">${ui.page==='warrants'&&(mode==='demo'?ui.actorId.startsWith('requester-'):s.user?.roles.includes('requester'))?`<button class="btn primary" data-action="request">${icon('plus')} Request warrant</button>`:ui.page==='audit'?`<button class="btn secondary" data-action="verify">${icon('shield')} ${mode==='demo'?'Check demo integrity':'Verify ledger'}</button>`:ui.page==='training'||ui.page==='overview'?`${mode==='live'?`<button class="btn secondary" data-action="prepare" ${!s.user?.roles.includes('owner')||['running','preparing','queued','finishing','completed'].includes(s.session?.status)?'disabled':''}>Prepare & pause</button>`:''}<button class="btn primary" data-action="advance" ${(mode==='demo'?s.rounds.length>=12:!s.user?.roles.includes('owner')||['running','preparing','queued','finishing','completed'].includes(s.session?.status))?'disabled':''}>${icon('plus')} Advance round</button>`:''}</div></div>${mode==='demo'?`<div class="demo-context">${icon('info',15)}<span>Illustrative metrics and simulated decisions. Real authorization, audit cryptography and model execution are not connected.</span><button class="text-button" data-action="reset">${icon('refresh',13)} Reset demo</button></div>`:''}${content}<footer class="workspace-footer"><span>Veylance <span class="footer-dot">/</span> Purpose-bound collaboration</span><span>${mode==='demo'?'Synthetic clock':'Updated'} · ${fmtDate(s.clock)}</span></footer></main></div></div>`;}
const scenarioSteps=[['Begin with an authorized network','All three hospitals hold an approved warrant. Advance the next illustrative round.','Advance round 5'],['Test a restricted feature','Hospital B will attempt to use a feature outside its approved scope.','Simulate restricted request'],['Withdraw Hospital B’s participation','Revoke its warrant. Previously aggregated updates and downloaded models remain.','Review & revoke warrant'],['Check the next contribution','Attempt the next round: Hospital B’s revoked warrant must be rejected.','Simulate next round'],['Continue with A and C','Hospital B is excluded from subsequent attempts. The remaining hospitals continue.','Continue with A & C'],['Scenario complete','You denied a restricted field, revoked a warrant and continued with two hospitals.','Reset scenario']];
export function scenario(s){const step=scenarioSteps[s.scenario]??scenarioSteps[5];return `<section class="scenario-bar" aria-labelledby="scenario-title"><div class="scenario-number">${String(Math.min(s.scenario+1,5)).padStart(2,'0')}<span>/ 05</span></div><div class="scenario-copy"><div class="eyebrow">GUIDED DEMONSTRATION ${s.scenario===5?'· COMPLETE':''}</div><h2 id="scenario-title">${step[0]}</h2><p>${step[1]}</p></div><button class="btn secondary small" data-action="scenario">${step[2]} ${icon('arrow',15)}</button></section>`;}
function totals(s){return {accepted:s.rounds.reduce((n,r)=>n+r.accepted.length,0),rejected:s.rounds.reduce((n,r)=>n+r.rejected.length,0)};}
function chartPanel(s,large=false){return `<section class="panel chart-panel ${large?'large-chart':''}"><div class="panel-heading"><div><h2>Model progression</h2><p>${modeCopy('Pooled synthetic holdout · no training executed',esc(latestRound(s).evaluation))}</p></div>${fixtureNote()}</div><div class="chart-toolbar"><div class="chart-legend"><span></span><strong id="chart-metric-label">Global accuracy</strong></div><div class="segmented" role="group" aria-label="Chart metric"><button class="selected" data-action="chart" data-metric="accuracy" aria-pressed="true">Accuracy</button><button data-action="chart" data-metric="loss" aria-pressed="false">Loss</button></div></div><div class="chart-wrap"><canvas id="progress-chart" role="img" aria-label="Accuracy and loss progression across rounds. Values are also available in the round history table."></canvas></div><div class="chart-foot">${icon('info',13)} ${modeCopy('Values are fixtures, not measured training results.','Backend evaluation · see model provenance.')}<a href="#/training">Round history ${icon('arrow',13)}</a></div></section>`;}
function hospitalTable(s){return `<section class="panel"><div class="panel-heading"><div><h2>Hospital participation</h2><p>${modeCopy('Fictional institutions · one scoped research purpose','Research consortium · purpose-bound participation')}</p></div><span class="subtle-count">03 institutions</span></div><div class="table-scroll"><table><caption class="sr-only">Hospital participation and effective warrant status</caption><thead><tr><th>Institution</th><th>Participation</th><th>Warrant</th><th>Contributions</th><th><span class="sr-only">Details</span></th></tr></thead><tbody>${s.hospitals.map(h=>{const w=(hospitalWarrant(s,h.id)??{id:'—',used:0,quota:1,status:'unavailable'});const status=statusOf(w,s);return `<tr><td><div class="hospital-cell">${hospitalMark(h.id)}<div><strong>${h.name}</strong><span>${h.subtitle}</span></div></div></td><td>${badge(status,status==='approved'?'Authorized':status)}</td><td><button class="link-button mono" data-action="detail" data-id="${w.id}">${w.id}</button></td><td><span class="mono">${w.used}<span class="muted"> / ${w.quota}</span></span><div class="quota-bar"><span style="width:${w.used/w.quota*100}%"></span></div></td><td><button class="icon-button" data-action="detail" data-id="${w.id}" aria-label="View ${w.id}">${icon('chevron',16)}</button></td></tr>`;}).join('')}</tbody></table></div></section>`;}
export function overview(s){const last=latestRound(s),n=totals(s),authorized=s.hospitals.filter(h=>statusOf((hospitalWarrant(s,h.id)??{id:'—',used:0,quota:1,status:'unavailable'}),s)==='approved').length;return `${isDemo()?scenario(s):liveControls(s)}<section class="summary-strip" aria-label="Session summary"><div><span>Authorized hospitals</span><strong>${authorized}<small>/ 3</small></strong><em>Effective participation</em></div><div><span>Communication round</span><strong>${String(last.number).padStart(2,'0')}<small>/ ${s.session?.plannedRounds??12}</small></strong><em>${modeCopy('Illustrative session','Training session')}</em></div><div><span>Contributions accepted</span><strong>${n.accepted}<small class="${n.rejected?'danger-text':''}">${n.rejected} rejected</small></strong><em>Cumulative update decisions</em></div><div><span>Global accuracy ${fixtureNote()}</span><strong>${pct(last.metrics.accuracy)}</strong><em>Model ${last.modelVersion} · ${modeCopy('pooled fixture','backend evaluation')}</em></div></section><div class="overview-top">${chartPanel(s)}<section class="panel session-panel"><div class="panel-heading"><h2>Current session</h2>${badge('approved',isDemo()?(s.rounds.length>=12?'Complete':'In progress'):(s.session?.status??'Not started'))}</div><div class="session-name"><span class="eyebrow">${isDemo()?'FL-READMISSION-001':esc(s.session?.id??'No active session')}</span><h3>Learning together.<br>Within agreed limits.</h3></div><dl class="key-values"><div><dt>Global model</dt><dd class="mono">${last.modelVersion}</dd></div><div><dt>Prediction target</dt><dd class="mono small-text">readmitted_lt30d</dd></div><div><dt>Update method</dt><dd>${modeCopy('FedAvg · illustrative',esc(last.aggregation))}</dd></div><div><dt>Approved features</dt><dd>4</dd></div></dl><div class="session-progress"><div><span>Session progression</span><strong>${last.number} of ${s.session?.plannedRounds??12} rounds</strong></div><div class="progress-track"><span style="width:${last.number/(s.session?.plannedRounds??12)*100}%"></span></div></div><a class="session-link" href="#/training">Open training workspace ${icon('arrow',16)}</a></section></div>${hospitalTable(s)}<section class="panel decisions-panel"><div class="panel-heading"><div><h2>Recent authorization decisions</h2><p>The latest activity across the research network</p></div><a class="text-link" href="#/audit">Full audit history ${icon('arrow',14)}</a></div><div class="decision-list">${s.audit.slice(-4).reverse().map(e=>`<div class="decision-row"><span class="decision-icon ${e.action.includes('denied')||e.action.includes('revoked')?'denied':''}">${icon(e.action.includes('denied')?'close':'check',15)}</span><div><strong>${esc(e.action)}</strong><span>${esc(e.hospitalId?`Hospital ${e.hospitalId} · ${e.warrantId}`:e.detail?.length>160?e.detail.slice(0,157)+'…':e.detail)}</span></div><time>${fmtDate(e.at)}</time></div>`).join('')}</div></section>`;}
const searchBox=(placeholder,value)=>`<div class="search-box">${icon('search',17)}<input id="table-search" type="search" placeholder="${placeholder}" aria-label="${placeholder}" value="${esc(value)}"></div>`;
function selectFilter(id,label,options,value){return `<label class="filter-select"><span class="sr-only">${label}</span><select id="${id}" aria-label="${label}">${options.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${l}</option>`).join('')}</select></label>`;}
export function warrants(s,ui){const list=s.warrants.filter(w=>(ui.filter==='all'||statusOf(w,s)===ui.filter)&&JSON.stringify(w).toLowerCase().includes(ui.search.toLowerCase()));return `<div class="scope-note">${icon('lock',17)}<div><strong>Purpose-bound access</strong><span class="mono">${PURPOSE}</span></div><span class="mono resource-label">${RESOURCE}</span></div><section class="panel"><div class="table-toolbar">${searchBox('Search warrants or hospitals',ui.search)}${selectFilter('status-filter','Warrant status',[['all','All statuses'],...['approved','pending','awaiting_acceptance','revoked','rejected','expired','exhausted'].map(s=>[s,s.replaceAll('_',' ')])],ui.filter)}${paginationLabel(list.length)}</div>${list.length?`<div class="table-scroll"><table><caption class="sr-only">Digital warrants</caption><thead><tr><th>Warrant / institution</th><th>Status</th><th>Approved operations</th><th>Expiry</th><th>Allowance</th><th></th></tr></thead><tbody>${list.map(w=>`<tr><td><button class="link-button mono" data-action="detail" data-id="${w.id}">${w.id}</button><span class="cell-sub">Hospital ${w.hospitalId} · Readmission research</span></td><td>${badge(statusOf(w,s))}</td><td><div class="operation-list">${w.operations.map(o=>`<span>${esc(o)}</span>`).join('')}</div></td><td class="nowrap small-text">${fmtDate(w.expiresAt)}</td><td class="mono">${w.used} <span class="muted">/ ${w.quota}</span></td><td><button class="icon-button" data-action="detail" data-id="${w.id}" aria-label="View ${w.id}">${icon('chevron',16)}</button></td></tr>`).join('')}</tbody></table></div>`:empty('No matching warrants','Try another search or status filter.')}<div class="table-footer">Three reviewer slots. No self-approval. Narrowing only.</div></section><div class="two-notes"><div>${icon('document',20)}<h3>Approval is specific</h3><p>Resource, purpose, operations, features, expiry and contribution allowance are part of each warrant.</p></div><div>${icon('history',20)}<h3>Revocation looks forward</h3><p>Future contributions are blocked. Prior aggregated updates and downloaded models are not erased.</p></div></div>`;}
export function training(s){const last=latestRound(s),n=totals(s);return `${isDemo()?'':liveControls(s)}<div class="training-session"><div><span class="eyebrow">SESSION ${isDemo()?'FL-READMISSION-001':esc(s.session?.id??'No active session')}</span><h2>Hospital readmission model</h2><p>Binary classification · target <code>readmitted_lt30d</code></p></div><div class="session-version"><span>GLOBAL MODEL</span><strong>${last.modelVersion}</strong>${fixtureNote()}</div></div><div class="training-hospitals">${s.hospitals.map(h=>{const w=(hospitalWarrant(s,h.id)??{id:'—',used:0,quota:1,status:'unavailable'});return `<div>${hospitalMark(h.id)}<div><strong>${h.name}</strong>${badge(statusOf(w,s),s.session?.experiment==='notebook-fedavg'&&h.id==='B'&&s.session.round>=14?'Omitted after R14':statusOf(w,s)==='approved'?'Participating':statusOf(w,s))}</div><span class="mono">${w.used}<small> accepted</small></span></div>`;}).join('')}</div><div class="metric-ribbon">${[['Accuracy',last.metrics.accuracy],['Precision',last.metrics.precision],['Recall',last.metrics.recall],['F1 score',last.metrics.f1],['ROC-AUC',last.metrics.rocAuc]].map(([k,v])=>`<div><span>${k}</span><strong>${k==='ROC-AUC'?number(v):pct(v)}</strong></div>`).join('')}<div class="metric-method">${fixtureNote()}<span>${modeCopy('Pooled synthetic holdout.<br>Binary positive class; no macro averaging.',esc(last.evaluation))}</span></div></div>${chartPanel(s,true)}<div class="training-bottom"><section class="panel"><div class="panel-heading"><div><h2>Local baseline vs federation</h2><p>${modeCopy('Illustrative pooled evaluation fixtures',s.session?.experiment==='notebook-fedavg'?'The notebook does not calculate local-only baselines':'Same pooled untouched tests · equal per-client training budget')}</p></div>${fixtureNote()}</div><div class="baseline-list">${s.hospitals.map(h=>`<div><span>${h.name} · local</span><div class="comparison-bar"><span style="width:${Number.isFinite(h.baseline)?h.baseline*100:0}%"></span></div><strong>${pct(h.baseline)}</strong></div>`).join('')}<div class="federated-comparison"><span>Federated model</span><div class="comparison-bar"><span style="width:${Number.isFinite(last.metrics.accuracy)?last.metrics.accuracy*100:0}%"></span></div><strong>${pct(last.metrics.accuracy)}</strong></div></div><p class="panel-note">${modeCopy('Same illustrative pooled holdout basis. No claim of measured improvement.',s.session?.experiment==='notebook-fedavg'?'Only the federated run is evaluated in the notebook FedAvg cell.':'Compare only evaluations using the same protocol and dataset.')}</p></section><section class="panel"><div class="panel-heading"><h2>Model provenance</h2></div><dl class="key-values provenance"><div><dt>Version</dt><dd>${last.modelVersion}</dd></div><div><dt>Timestamp</dt><dd>${fmtDate(last.at)}</dd></div><div><dt>Hash identifier</dt><dd><code>${last.modelHash}</code><small>${modeCopy('Non-cryptographic demo identifier',esc(last.modelHashAlgorithm||'Hash algorithm not supplied'))}</small></dd></div><div><dt>Feature schema</dt><dd>${featureChips(FEATURES)}</dd></div><div><dt>Model aggregation</dt><dd>${esc(last.aggregation)}</dd></div><div><dt>Evaluation method</dt><dd>${esc(last.evaluation)}</dd></div></dl></section></div><section class="panel"><div class="panel-heading"><div><h2>Round history</h2><p>${n.accepted} accepted · ${n.rejected} rejected contributions</p></div><span class="subtle-count">${s.rounds.length} / ${s.session?.plannedRounds??12} rounds</span></div><div class="table-scroll"><table><caption class="sr-only">Training round metrics</caption><thead><tr><th>Round / model</th><th>Accepted</th><th>Rejected</th><th>Accuracy</th><th>Loss</th><th>Timestamp</th></tr></thead><tbody>${s.rounds.slice().reverse().map(r=>`<tr><td class="mono">${String(r.number).padStart(2,'0')} <span class="muted">/ ${r.modelVersion}</span></td><td><span class="accepted-hospitals">${r.accepted.map(id=>`<span>${id}</span>`).join('')}</span></td><td>${r.rejected.length?r.rejected.map(e=>`<span class="danger-text small-text">${e.hospitalId} · ${esc(e.code)}</span>`).join('<br>'):'<span class="muted">—</span>'}</td><td class="mono">${pct(r.metrics.accuracy)}</td><td class="mono">${number(r.metrics.loss)}</td><td class="small-text nowrap">${fmtDate(r.at)}</td></tr>`).join('')}</tbody></table></div></section>`;}
export function security(s,ui){const list=s.events.filter(e=>(ui.filter==='all'||e.code===ui.filter)&&(ui.hospital==='all'||e.hospitalId===ui.hospital)&&JSON.stringify(e).toLowerCase().includes(ui.search.toLowerCase())).reverse();return `<div class="security-summary"><div class="security-total">${icon('shield',25)}<strong>${s.events.length}</strong><span>${modeCopy('simulated denials recorded','authorization denials recorded')}</span></div><div><span class="status-dot"></span> ${modeCopy('Policy boundary examples · demo only','Backend policy decisions')}</div></div><section class="panel"><div class="table-toolbar">${searchBox('Search events or denial reasons',ui.search)}${selectFilter('status-filter','Event type',[['all','All event types'],['FEATURE_DENIED','Unauthorized field'],['PURPOSE_MISMATCH','Incorrect purpose'],['EXPIRED','Expired warrant'],['REVOKED','Revoked participation'],['EXHAUSTED','Exhausted quota']],ui.filter)}${selectFilter('hospital-filter','Hospital',[['all','All hospitals'],['A','Hospital A'],['B','Hospital B'],['C','Hospital C']],ui.hospital)}</div>${list.length?`<div class="event-list">${list.map(e=>`<details class="event-item"><summary><span class="event-denied">${icon('close',16)}</span><div><strong>${esc(e.code.replaceAll('_',' '))}</strong><p>Hospital ${e.hospitalId} · ${esc(e.reason)}</p></div><time>${fmtDate(e.at)}</time>${icon('chevron',16)}</summary><div class="event-detail"><dl><div><dt>Event</dt><dd class="mono">${e.id}</dd></div><div><dt>Warrant</dt><dd><button class="link-button mono" data-action="detail" data-id="${e.warrantId}">${e.warrantId}</button></dd></div><div><dt>Decision</dt><dd>DENY ${modeCopy('· simulated','· backend decision')}</dd></div><div><dt>Requested operation</dt><dd class="mono">${esc(e.operation||'submit_update')}</dd></div><div><dt>Requested features</dt><dd>${featureChips(e.features||FEATURES)}</dd></div><div><dt>Explanation</dt><dd>${esc(e.reason)}</dd></div></dl>${e.sandbox?'<p class="panel-note">Disposable sandbox policy example. The active warrant was not changed.</p>':''}</div></details>`).join('')}</div>`:empty('No matching security events',s.events.length?'Try another search or filter.':'Run the guided scenario to see a restricted-field denial and revoked contribution.')}<div class="table-footer">${modeCopy('Denial reasons are generated by the isolated demo adapter.','Denial reasons are supplied by the protected backend.')}</div></section>${isDemo()?`<section class="policy-lab"><div><span class="eyebrow">EXPLORE THE POLICY BOUNDARY</span><h2>Try another denial.</h2><p>Each example uses a disposable copy of a warrant and creates a labelled demo event.</p></div><div><button class="btn secondary small" data-action="probe" data-kind="PURPOSE_MISMATCH">Incorrect purpose</button><button class="btn secondary small" data-action="probe" data-kind="EXPIRED">Expired warrant</button><button class="btn secondary small" data-action="probe" data-kind="EXHAUSTED">Exhausted quota</button></div></section>`:''}`;}
export function audit(s,ui){const list=s.audit.filter(e=>JSON.stringify(e).toLowerCase().includes(ui.search.toLowerCase()));return `<div class="integrity-banner ${ui.verification&&!ui.verification.valid?'integrity-error':''}">${icon('shield',25)}<div><strong>${ui.verification?esc(ui.verification.message):modeCopy('Demo ledger · verification not run','Ledger verification not run')}</strong><p>${ui.verification?`${ui.verification.count} entries checked · ${esc(ui.verification.method)} · ${fmtDate(ui.verification.verifiedAt)}`:modeCopy('Hash-like identifiers illustrate a chained record. Use “Check demo integrity” to run a non-cryptographic consistency check.','Run backend verification and inspect its method and trust anchor.')}</p></div><span class="fixture-label">${ui.verification?ui.verification.cryptographic?'Backend verification':'Demo check only':'Not cryptographically verified'}</span></div><section class="panel"><div class="table-toolbar">${searchBox('Search actor, action, warrant or hash',ui.search)}${paginationLabel(list.length)}</div>${list.length?`<div class="audit-list">${list.slice().reverse().map(e=>`<details class="audit-entry"><summary><span class="audit-marker">${icon('history',16)}</span><div><strong>${esc(e.action)}</strong><span>${esc(e.actor)} ${e.hospitalId?`· Hospital ${e.hospitalId}`:''}</span></div><code>${esc(e.hash)}</code><time>${fmtDate(e.at)}</time>${icon('chevron',15)}</summary><div class="audit-detail"><dl><div><dt>Record</dt><dd class="mono">${e.id}</dd></div><div><dt>Warrant</dt><dd>${e.warrantId?`<button class="link-button mono" data-action="detail" data-id="${e.warrantId}">${e.warrantId}</button>`:'Session-level event'}</dd></div><div><dt>Details</dt><dd>${esc(e.detail)}</dd></div><div><dt>Previous identifier</dt><dd class="mono">${esc(e.previousHash)}</dd></div><div><dt>Current identifier</dt><dd class="mono">${esc(e.hash)}</dd></div></dl></div></details>`).join('')}</div>`:empty('No matching audit entries','Try a different actor, action, warrant or identifier.')}</section><p class="disclosure-note">${icon('info',16)} ${modeCopy('Demo records can be reset and edited in browser storage. They are not a tamper-proof ledger. Actual cryptographic audit verification requires a trusted backend and external trust anchor.','The local SHA-256 chain detects inconsistent edits. No independent anchor is configured. An operator with full storage access can rewrite the complete chain; it is not immutable.')}</p>`;}
export function requestForm(s){return `<div class="dialog-heading"><div><span class="eyebrow">NEW AUTHORIZATION</span><h2 id="dialog-title">Request a warrant</h2></div><button class="icon-button" data-action="close" aria-label="Close request form">${icon('close')}</button></div><p class="dialog-intro">Define the minimum scope for this research task. Three independent reviewers must approve it.</p><form id="warrant-request"><div class="form-grid">${field('request-hospital','Requesting hospital',`<select name="hospitalId" id="request-hospital">${(isDemo()?['A','B','C']:(s?.user?.hospitals??[s?.user?.hospital]).filter(Boolean)).map(h=>`<option value="${h}" ${s?.user?.hospital===h?'selected':''}>Hospital ${h}</option>`).join('')}</select>`)}${field('request-duration','Duration (hours)','<input type="number" id="request-duration" name="duration" min="1" max="72" value="24" required>')}${field('request-resource','Resource',`<input id="request-resource" name="resource" value="${RESOURCE}" readonly>`)}${field('request-purpose','Purpose',`<input id="request-purpose" name="purpose" value="${PURPOSE}" readonly>`)}${field('request-quota','Contribution allowance','<input id="request-quota" name="quota" type="number" min="1" max="50" value="12" required>','One allowance unit per accepted model update.')}</div><fieldset><legend>Requested operations</legend>${OPERATIONS.map(op=>`<label class="checkbox-row"><input name="operations" type="checkbox" value="${op}" checked><span><code>${op}</code></span></label>`).join('')}</fieldset><fieldset><legend>Model features</legend>${FEATURES.map(f=>`<label class="checkbox-row"><input name="features" type="checkbox" value="${f}" checked><code>${f}</code></label>`).join('')}</fieldset><fieldset><legend>Risk controls</legend>${['No patient identifiers','Aggregate model updates only','Four-feature allowlist'].map(c=>`<label class="checkbox-row"><input name="controls" type="checkbox" value="${c}" checked><span>${c}</span></label>`).join('')}</fieldset><div class="form-error" role="alert"></div><div class="dialog-actions"><button type="button" class="btn secondary" data-action="close">Cancel</button><button class="btn primary" type="submit">${modeCopy('Submit demo request','Submit request')} ${icon('arrow',16)}</button></div></form>`;}
export function warrantDetail(s,id,actorId,demo=false){const w=s.warrants.find(w=>w.id===id);if(!w)return empty('Warrant not found','The demo may have been reset.');const status=statusOf(w,s),canReview=demo?REVIEWERS.some(r=>r.id===actorId):s.user?.roles.some(role=>['manager','risk','owner'].includes(role))&&s.user.sub!==w.requesterId;return `<div class="dialog-heading"><div><span class="eyebrow">WARRANT DETAILS</span><h2 id="dialog-title">${w.id}</h2></div><button class="icon-button" data-action="close" aria-label="Close warrant details">${icon('close')}</button></div><div class="detail-status">${hospitalMark(w.hospitalId)}<strong>Hospital ${w.hospitalId}</strong>${badge(status)}</div><dl class="detail-scope"><div><dt>Resource</dt><dd><code>${w.resource}</code></dd></div><div><dt>Purpose</dt><dd><code>${w.purpose}</code></dd></div><div><dt>Requester</dt><dd>${esc(w.requesterName)}</dd></div><div><dt>Expiry</dt><dd>${fmtDate(w.expiresAt)}</dd></div><div><dt>Scope version</dt><dd>${w.scopeVersion??1}</dd></div><div><dt>Contribution allowance</dt><dd>${w.used} used / ${w.quota} approved</dd></div></dl><section class="drawer-section"><h3>${status==='approved'?'Effective permissions':'Requested / retained scope'}</h3>${status!=='approved'?'<p class="panel-note">No effective permission is granted while this warrant is inactive.</p>':''}<span class="field-hint">OPERATIONS</span><div class="chip-group">${featureChips(w.operations)}</div><span class="field-hint">FEATURE ALLOWLIST</span><div class="chip-group">${featureChips(w.features)}</div></section>${demo?`<div class="drawer-role"><label for="drawer-actor">Demo actor</label><select id="drawer-actor">${[...REVIEWERS.map(r=>({id:r.id,label:r.label})),...s.hospitals.map(h=>({id:`requester-${h.id}`,label:`Requester · Hospital ${h.id}`}))].map(a=>`<option value="${a.id}" ${actorId===a.id?'selected':''}>${a.label}</option>`).join('')}</select></div>`:''}<section class="drawer-section"><h3>Independent review <span class="muted">${w.reviews.length} / 3</span></h3>${REVIEWERS.map(r=>{const review=w.reviews.find(rv=>rv.role===r.role);return `<div class="reviewer-row"><span class="reviewer-icon ${review?'reviewed':''}">${icon(review?'check':'clock',16)}</span><div><strong>${r.label}</strong><span>${esc(review?.name??(demo?r.name:'Awaiting verified reviewer'))}</span></div><span class="small-text ${review?'green-text':'muted'}">${review?esc(review.decision):'Awaiting review'}</span></div>`;}).join('')}<p class="panel-note">Distinct identities. No self-approval. Scope narrowing clears earlier approvals.</p></section>${w.narrowed?`<div class="narrow-notice">${icon('info',17)}<p><strong>Narrowed scope</strong><br>${w.consentAt?'Requester accepted at '+fmtDate(w.consentAt):'Requester consent is required after all three reviews.'}</p></div>`:''}<section class="drawer-section"><h3>Risk controls</h3><ul class="controls-list">${w.controls.map(c=>`<li>${icon('check',14)}${esc(c)}</li>`).join('')}</ul></section><section class="drawer-section"><h3>Approval history</h3><ol class="history-list">${w.history.map(h=>`<li><strong>${esc(h.action)}</strong><span>${esc(h.actor)} · ${fmtDate(h.at)}</span></li>`).join('')}</ol></section><div class="form-error" role="alert"></div><div class="dialog-actions sticky-actions">${status==='pending'&&canReview?`<button class="btn danger-outline" data-action="reject" data-id="${id}">Reject</button><button class="btn secondary" data-action="narrow" data-id="${id}">Narrow scope</button><button class="btn primary" data-action="approve" data-id="${id}">Approve slot</button>`:status==='awaiting_acceptance'&&actorId===w.requesterId?`<button class="btn primary" data-action="accept" data-id="${id}">Accept narrowed scope</button>`:status==='approved'||status==='exhausted'?`${canReview?`<button class="btn danger-outline" data-action="revoke" data-id="${id}">${icon('close',15)} Revoke warrant</button>`:''}${!demo&&actorId===w.requesterId?`<button class="btn secondary" data-action="download" data-id="${id}">Download model</button>`:''}`:'<span class="field-hint">No action available for this account.</span>'}</div>`;}
export function narrowForm(s,id){const w=s.warrants.find(w=>w.id===id);return `<div class="dialog-heading"><div><span class="eyebrow">SCOPE REVIEW</span><h2 id="dialog-title">Narrow permissions</h2></div><button class="icon-button" data-action="close" aria-label="Close narrowing form">${icon('close')}</button></div><p class="dialog-intro">${id} · Only remove permissions, shorten expiry or reduce allowance. Earlier approvals will be cleared; requester consent follows three reviews.</p><form id="narrow-form" data-id="${id}"><fieldset><legend>Retained features</legend>${w.features.map(f=>`<label class="checkbox-row"><input type="checkbox" name="features" value="${f}" checked><code>${f}</code></label>`).join('')}</fieldset><fieldset><legend>Retained operations</legend>${w.operations.map(f=>`<label class="checkbox-row"><input type="checkbox" name="operations" value="${f}" checked><code>${f}</code></label>`).join('')}</fieldset>${field('narrow-quota','Contribution allowance',`<input type="number" min="1" max="${w.quota}" value="${w.quota}" id="narrow-quota" name="quota" required>`)}${field('narrow-expiry','Expiry (UTC)',`<input type="datetime-local" id="narrow-expiry" name="expiresAt" max="${w.expiresAt.slice(0,16)}" value="${w.expiresAt.slice(0,16)}" required>`)}<div class="form-error" role="alert"></div><div class="dialog-actions"><button class="btn secondary" type="button" data-action="detail" data-id="${id}">Back</button><button class="btn primary" type="submit">Narrow & approve slot</button></div></form>`;}
export function revokeForm(s,id){const w=s.warrants.find(w=>w.id===id);return `<div class="dialog-heading"><div><span class="eyebrow">WITHDRAW PARTICIPATION</span><h2 id="dialog-title">Revoke Hospital ${w.hospitalId}’s warrant?</h2></div><button class="icon-button" data-action="close" aria-label="Close revocation dialog">${icon('close')}</button></div><p class="dialog-intro">${id} · Future contributions will be denied. Previously aggregated updates and downloaded models remain. This does not perform federated unlearning.</p><form id="revoke-form" data-id="${id}">${field('revoke-reason','Reason','<textarea id="revoke-reason" name="reason" rows="3" maxlength="300" required>Participation withdrawn following scope review.</textarea>')}<div class="form-error" role="alert"></div><div class="dialog-actions"><button class="btn secondary" type="button" data-action="close">Cancel</button><button class="btn danger" type="submit">${modeCopy('Revoke demo warrant','Revoke warrant')}</button></div></form>`;}

export function predictionPanel(s,result){
 if(!s.user?.roles.includes('requester'))return '';
 const eligible=s.warrants.filter(w=>s.session?.bindings?.some(b=>b.warrantId===w.id&&b.hospitalId===w.hospitalId)&&w.requesterId===s.user.sub&&(s.user.hospitals??[s.user.hospital]).includes(w.hospitalId)&&w.status==='approved'&&w.operations.includes('download_model'));const w=eligible[0];
 const ready=!!w&&!!s.session?.round;
 const controls=[['emergency_admission','Emergency admission',0,1],['prior_inpatient_visits','Prior inpatient visits',0,8],['length_of_stay','Length of stay (days)',1,18],['medication_count','Medication count',1,30]];
 return `<section class="panel prediction-panel"><div class="panel-heading"><div><h2>Readmission prediction</h2><p>Latest FL model · synthetic research demonstration</p></div></div><p class="panel-note">Enter the four approved features. The server calculates the result from the latest trained model. Do not enter patient identifiers or clinical data.</p>${ready?`<form id="prediction-form">${eligible.length>1?field('predict-hospital','Predict under hospital warrant',`<select id="predict-hospital" name="warrantId">${eligible.map(x=>`<option value="${esc(x.id)}" ${result?.warrantId===x.id?'selected':''}>Hospital ${x.hospitalId} · ${esc(x.id)}</option>`).join('')}</select>`):`<input type="hidden" name="warrantId" value="${esc(w.id)}">`}<div class="prediction-fields">${controls.map(([name,label,min,max])=>field('predict-'+name,label,`<input type="number" name="${name}" id="predict-${name}" min="${min}" max="${max}" step="1" value="${min}" required>`)).join('')}</div><button class="btn primary" type="submit">Predict readmission</button><div class="form-error" role="alert"></div></form>${result&&result.sessionId===s.session.id&&result.modelVersion===s.session.round?`<div class="prediction-result" role="status"><strong>${(result.probability*100).toFixed(1)}% estimated probability</strong><span>Hospital ${esc(eligible.find(x=>x.id===result.warrantId)?.hospitalId??w.hospitalId)} · Model v${result.modelVersion} · ${result.prediction?'Above':'Below'} the 50% decision threshold</span></div>`:''}`:`<p class="panel-note">${s.session?.round?'An active, approved warrant with model access is required.':'The owner must complete at least one FL round before predictions are available.'}</p>`}</section>`;
}

function liveControls(s){const owner=s.user?.roles.includes('owner'),canCreate=!s.session||['ready','completed','failed'].includes(s.session.status);const chooser=owner&&canCreate?`<label class="round-selector" for="planned-rounds"><span>New-session rounds</span><input id="planned-rounds" type="number" min="1" step="1" value="4" aria-label="Rounds for the next training session"></label><button class="btn secondary small" data-action="new-session">New session</button>`:'';return `<section class="live-context"><div><span class="eyebrow">MEASURED ON SYNTHETIC DATA</span><h2>${esc(s.session?.status??'Ready for governed research')}</h2>${s.session?.error?`<p>${esc(s.session.error)}</p>`:''}</div><div class="live-actions">${chooser}${s.session?`${s.session.status==='queued'?'<button class="btn primary small" data-action="commit">Accept queued updates</button>':''}`:''}</div></section>`;}

function hospitalWarrant(s,h){const id=s.session?.bindings?.find(b=>b.hospitalId===h)?.warrantId;return s.warrants.find(w=>w.id===id)??s.warrants.findLast(w=>w.hospitalId===h);}
